const sh = wb.getWorksheet('Sheet1');
const rng = sh.getRange('A2:D8');
const rows = rng.getValues();
const out: any[][] = [];
const idx = new Map<any, number>();
for (const r of rows) {
  if (idx.has(r[0])) { out[idx.get(r[0])!][3] += r[3]; }
  else { idx.set(r[0], out.length); out.push([...r]); }
}
rng.clear('values');
sh.getRange('A2:D' + (1 + out.length)).setValues(out);
rng.getStyle().setFont({ bold: false, color: '#000000' });
sh.getRange('D2:D8').getStyle().setNumberFormat('0');
out.length

