const sh = wb.getWorksheet('Sheet1');
const r = [] as any[];
for (let row=2; row<=8; row++) r.push(['A','B','C','D'].map(c=>{const x=sh.getRange(c+row).getCell(); const f=x.getStyle().getFont(); return `${x.getValue()}|${x.getText()}|${f.getWeight?.()}|${f.getColor?.()}`}).join('  ;  '));
log(r.join('\n'));
log('merges A:D', JSON.stringify(sh.getRange('A1:D8').getMerges()), 'merges all', JSON.stringify(sh.getRange('A1:J9').getMerges()));
log(sh.getRange('F1:H8'));
sh.getRange('A1:J9')

